          {
            "op": "fact",
            "path": "/vendor/countryRisk",
            "operator": "equals",
            "value": "MEDIUM"
          },
          {
            "op": "fact",
            "path": "/vendor/riskScore",
            "operator": "less-than",
            "value": "40"
          },
          {
            "op": "fact",
            "path": "/vendor/requestedSpend",
            "operator": "less-than-or-equal",
            "value": "100000.00"
          }
        ]
      },
      "outcome": "approve",
      "onUnknown": "ignore",
      "evidenceRequirementRefs": [
        "financial-evidence"
      ]
    },
    {
      "id": "d-eight-review",
      "description": "D8 sends every remaining clear-screening request to review.",
      "when": {
        "op": "fact",
        "path": "/vendor/sanctionsStatus",
        "operator": "equals",
        "value": "CLEAR"
      },
      "outcome": "review",
      "onUnknown": "ignore",
      "evidenceRequirementRefs": [
        "financial-evidence"
      ]
    },
    {
      "id": "u-one-unreadable",
      "description": "U1 blocks resolution when a risk, spend, or country input is unreadable and no invariant determination has suppressed this rule.",
      "when": {
        "op": "not",
        "condition": {
          "op": "all",
          "conditions": [
            {
              "op": "any",
              "conditions": [
                {
                  "op": "fact",
                  "path": "/vendor/riskScore",
                  "operator": "greater-than-or-equal",
                  "value": "0"
                },
                {
                  "op": "fact",
                  "path": "/vendor/riskScore",
                  "operator": "less-than-or-equal",
                  "value": "100"
                }
              ]
            },
            {
              "op": "any",
              "conditions": [
                {
                  "op": "fact",
                  "path": "/vendor/requestedSpend",
                  "operator": "greater-than-or-equal",
                  "value": "0.00"
                },
                {
                  "op": "fact",
                  "path": "/vendor/requestedSpend",
                  "operator": "less-than-or-equal",
                  "value": "10000000.00"
                }
              ]
            },
            {
              "op": "fact",
              "path": "/vendor/countryRisk",
              "operator": "in",
              "value": [
                "LOW",
                "MEDIUM",
                "HIGH"
              ]
            }
          ]
        }
      },
      "outcome": "review",
      "onUnknown": "escalate"
    }
  ],
  "exceptions": [
